public class Solution
{
    public int[] MergeSortedIntoFirst(int[] first, int realCount, int[] second)
    {
        int a = realCount - 1, b = second.Length - 1, write = first.Length - 1;
        while (b >= 0)
        {
            if (a >= 0 && first[a] > second[b])
                first[write--] = first[a--];
            else
                first[write--] = second[b--];
        }
        return first;
    }
}

