function FindMissingInt(file, smallMemory) {
  let block = 0;
  if (smallMemory) {
    const counts = new Uint32Array(2048);
    for (let value; (value = file.ReadNext()) !== -1; ) ++counts[value >>> 20];
    while (counts[block] === 1 << 20) ++block;
