class Solution {
  public int AdditionOnlyArithmetic(int first, int second, String operation) {
    class Negator {
      int opposite(int value) {
        int step = value < 0 ? 1 : -1, result = 0;
        while (value != 0) {
          value += step;
          result += step;
        }
        return result;
      }
