        divisor = second < 0 ? negator.opposite(second) : second,
        remove = negator.opposite(divisor), step = (first < 0) == (second < 0) ? 1 : -1,
        quotient = 0;
    while (remaining + remove >= 0) {
      remaining += remove;
      quotient += step;
    }
    return quotient;
  }
