class Solution {
 public:
  std::vector<int> BestLine(const std::vector<std::vector<int>>& points) {
    if (points.empty())
      return {};
    auto gcd = [](int a, int b) {
      while (b != 0) {
        int next = a % b;
        a = b;
        b = next;
      }
      return a;
    };
    std::vector<int> best{1, 0, -points[0][0]};
    int bestCount = 0;
    for (size_t anchor = 0; anchor < points.size(); ++anchor) {
