        int length = symbol == 'a' ? lengthA : lengthB;
        auto part = text.substr(offset, length);
        if (symbol == 'a') {
          if (!haveA) {
            a = part;
            haveA = true;
          } else if (a != part) {
            valid = false;
            break;
          }
        } else {
          if (!haveB) {
            b = part;
            haveB = true;
          } else if (b != part) {
            valid = false;
            break;
          }
        }
        offset += length;
      }
      if (valid && offset == n)
        return true;
    }
    return false;
  }
};

