class Solution {
  public void Shuffle(int[] values) {
    for (int index = values.length - 1; index > 0; --index) {
      int other = RandomSource.GetRandom(0, index), saved = values[index];
      values[index] = values[other];
      values[other] = saved;
    }
  }
}

