def RandomSubset(values: list[int], count: int) -> list[int]:
    reservoir = values[:count]
    if count == 0:
        return reservoir
    for index in range(count, len(values)):
        slot = RandomSource.GetRandom(0, index)
        if slot < count:
            reservoir[slot] = values[index]
    return reservoir

